to main:
    let count_input be ask for a number ""
    let count be value of count_input
    let seen be a map from number to number
    let duplicate be no
    repeat count times:
        let number_input be ask for a number ""
        let number_value be value of number_input
        if seen contains number_value:
            set duplicate to yes
        otherwise:
            set item number_value of seen to 1
    if duplicate:
        say 0
    otherwise:
        let numbers be keys of seen
        let smallest be (item 2 of numbers) - (item 1 of numbers)
        if length of numbers is more than 2:
            for each index from 3 to length of numbers:
                let gap be (item index of numbers) - (item (index - 1) of numbers)
                if gap is less than smallest:
                    set smallest to gap
        say smallest

