import sys


def main():
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    counts = {}
    for word in lines[1:n + 1]:
        counts[word] = counts.get(word, 0) + 1
    print(",".join(f"{word}:{counts[word]}" for word in sorted(counts)))


if __name__ == "__main__":
    main()

