def main():
    line = sys.stdin.readline().rstrip("\n\r")
    matching = {")": "(", "]": "[", "}": "{"}
    stack = []
    for bracket in line:
        if bracket in "([{":
            stack.append(bracket)
        elif not stack or stack.pop() != matching[bracket]:
            print("no")
            return
    print("yes" if not stack else "no")


if __name__ == "__main__":
