use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut counts = BTreeMap::new();
    for _ in 0..n {
        let word = tokens.next().unwrap().to_string();
        *counts.entry(word).or_insert(0usize) += 1;
    }
    let output = counts
        .iter()
        .map(|(word, count)| format!("{}:{}", word, count))
        .collect::<Vec<_>>()
        .join(",");
    println!("{}", output);
}

source_texts.binary_search_queries:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let values: Vec<i128> = (0..n)
        .map(|_| tokens.next().unwrap().parse().unwrap())
        .collect();
    let q: usize = tokens.next().unwrap().parse().unwrap();
    let answers = (0..q)
        .map(|_| {
            let query: i128 = tokens.next().unwrap().parse().unwrap();
            values
                .binary_search(&query)
                .map(|index| index + 1)
                .unwrap_or(0)
                .to_string()
        })
        .collect::<Vec<_>>()
        .join(",");
    println!("{}", answers);
}

source_texts.sparse_dot_product:
use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut first = HashMap::with_capacity(n);
    for _ in 0..n {
        let index: u128 = tokens.next().unwrap().parse().unwrap();
        let value: i128 = tokens.next().unwrap().parse().unwrap();
        first.insert(index, value);
    }
    let m: usize = tokens.next().unwrap().parse().unwrap();
    let mut result = 0i128;
    for _ in 0..m {
        let index: u128 = tokens.next().unwrap().parse().unwrap();
        let value: i128 = tokens.next().unwrap().parse().unwrap();
        if let Some(other) = first.get(&index) {
            result += other * value;
        }
    }
    println!("{}", result);
}

