use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let year: u128 = tokens.next().unwrap().parse().unwrap();
    let month: i32 = tokens.next().unwrap().parse().unwrap();
    let day: i32 = tokens.next().unwrap().parse().unwrap();
    let leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
    let days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if leap => 29,
        2 => 28,
        _ => 0,
    };
    println!("{}", if day >= 1 && day <= days { "yes" } else { "no" });
}

