sources.binary_search_queries:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let values: Vec<i128> = (0..n)
        .map(|_| tokens.next().unwrap().parse().unwrap())
        .collect();
    let q: usize = tokens.next().unwrap().parse().unwrap();
    let answers = (0..q)
        .map(|_| {
            let query: i128 = tokens.next().unwrap().parse().unwrap();
            values.binary_search(&query).map_or(0, |index| index + 1).to_string()
        })
        .collect::<Vec<_>>()
        .join(",");
    println!("{answers}");
}

sources.caesar_shift:
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let shift: u8 = lines.next().unwrap().unwrap().trim().parse().unwrap();
    let text = lines.next().transpose().unwrap().unwrap_or_default();
    let shifted: String = text
        .bytes()
        .map(|byte| (b'a' + (byte - b'a' + shift) % 26) as char)
        .collect();
    println!("{shifted}");
}

sources.gregorian_date_validity:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let values: Vec<i128> = input
        .split_whitespace()
        .map(|value| value.parse().unwrap())
        .collect();
    let year = values[0];
    let month = values[1];
    let day = values[2];
    let leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
    let days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if leap => 29,
        2 => 28,
        _ => 0,
    };
    println!("{}", if day >= 1 && day <= days { "yes" } else { "no" });
}

