use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut main_sum = 0i128;
    let mut opposite_sum = 0i128;
    for row in 0..n {
        for column in 0..n {
            let value: i128 = tokens.next().unwrap().parse().unwrap();
            if row == column {
                main_sum += value;
            }
            if row + column + 1 == n {
                opposite_sum += value;
            }
        }
    }
    println!("{}", (main_sum - opposite_sum).abs());
}

sources.nearest_pair_gap:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut values: Vec<i128> = (0..n)
        .map(|_| tokens.next().unwrap().parse().unwrap())
        .collect();
    values.sort_unstable();
    let gap = values
        .windows(2)
        .map(|pair| pair[1] - pair[0])
        .min()
        .unwrap();
    println!("{gap}");
}

sources.polynomial_value:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let degree: usize = tokens.next().unwrap().parse().unwrap();
    let coefficients: Vec<i128> = (0..=degree)
        .map(|_| tokens.next().unwrap().parse().unwrap())
        .collect();
    let x: i128 = tokens.next().unwrap().parse().unwrap();
    let result = coefficients
        .into_iter()
        .fold(0i128, |value, coefficient| value * x + coefficient);
    println!("{result}");
}

