    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut main_sum = 0i128;
    let mut opposite_sum = 0i128;
    for row in 0..n {
        for column in 0..n {
            let value: i128 = it.next().unwrap().parse().unwrap();
            if row == column {
                main_sum += value;
            }
            if row + column + 1 == n {
                opposite_sum += value;
            }
        }
    }
    println!("{}", (main_sum - opposite_sum).abs());
}

