            '(' | '[' | '{' => stack.push(bracket),
            ')' | ']' | '}' => {
                let expected = match bracket { ')' => '(', ']' => '[', _ => '{' };
                if stack.pop() != Some(expected) {
                    valid = false;
                    break;
                }
            }
            _ => unreachable!(),
        }
    }
    println!("{}", if valid && stack.is_empty() { "yes" } else { "no" });
}

