use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let values: Vec<i128> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();
    let q: usize = it.next().unwrap().parse().unwrap();
    let answers = (0..q)
        .map(|_| {
            let query: i128 = it.next().unwrap().parse().unwrap();
            values.binary_search(&query).map_or(0, |index| index + 1).to_string()
        })
        .collect::<Vec<_>>()
        .join(",");
    println!("{}", answers);
}

sources.caesar_shift:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let (first, rest) = input.split_once('\n').unwrap_or((&input, ""));
    let shift: u8 = first.trim_end_matches('\r').trim().parse().unwrap();
    let line = rest.split_once('\n').map_or(rest, |(line, _)| line).trim_end_matches('\r');
    let output: String = line
        .bytes()
        .map(|byte| (b'a' + (byte - b'a' + shift) % 26) as char)
        .collect();
    println!("{}", output);
}

sources.gregorian_date_validity:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let year: i128 = it.next().unwrap().parse().unwrap();
    let month: i32 = it.next().unwrap().parse().unwrap();
    let day: i32 = it.next().unwrap().parse().unwrap();
    let leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
    let days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if leap => 29,
        2 => 28,
        _ => 0,
    };
    println!("{}", if day >= 1 && day <= days { "yes" } else { "no" });
}

