use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let degree: usize = it.next().unwrap().parse().unwrap();
    let coefficients: Vec<i128> = (0..=degree)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();
    let x: i128 = it.next().unwrap().parse().unwrap();
    let value = coefficients.into_iter().fold(0i128, |value, coefficient| {
        value * x + coefficient
    });
    println!("{}", value);
}

sources.postfix_evaluation:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut stack: Vec<i128> = Vec::new();
    for _ in 0..n {
        let token = it.next().unwrap();
        match token {
            "+" | "-" | "*" => {
                let right = stack.pop().unwrap();
                let left = stack.pop().unwrap();
                stack.push(match token {
                    "+" => left + right,
                    "-" => left - right,
                    _ => left * right,
                });
            }
            _ => stack.push(token.parse().unwrap()),
        }
    }
    println!("{}", stack.pop().unwrap());
}

