to absolute with x as number giving number:
    if x is less than 0:
        give back 0 - x
    give back x

to main:
    let n_input be ask for a number ""
    let n be value of n_input
    let values be an empty list of number
    repeat n times:
        let value_input be ask for a number ""
        add (value of value_input) to values
    let best be (absolute with ((item 1 of values) - (item 2 of values)))
    for each i from 1 to n:
        if i is less than n:
            for each j from (i + 1) to n:
                let gap be (absolute with ((item i of values) - (item j of values)))
                if gap is less than best:
                    set best to gap
    say best

