import sys


def main():
    lines = sys.stdin.buffer
    n = int(lines.readline())
    stack = []
    for _ in range(n):
        token = lines.readline().decode().strip()
        if token in {"+", "-", "*"}:
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            else:
                stack.append(left * right)
        else:
            stack.append(int(token))
    print(stack[-1])


if __name__ == "__main__":
    main()

