source_texts.binary_search_queries:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let values: Vec<i128> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();
    let q: usize = it.next().unwrap().parse().unwrap();
    let answers: Vec<String> = (0..q)
        .map(|_| {
            let query: i128 = it.next().unwrap().parse().unwrap();
            values
                .binary_search(&query)
                .map_or(0, |index| index + 1)
                .to_string()
        })
        .collect();
    println!("{}", answers.join(","));
}

source_texts.nearest_pair_gap:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut values: Vec<i128> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();
    values.sort_unstable();
    let answer = values
        .windows(2)
        .map(|pair| pair[1] - pair[0])
        .min()
        .unwrap();
    println!("{answer}");
}

source_texts.inventory_ledger:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut balances: BTreeMap<&str, i128> = BTreeMap::new();
    for _ in 0..n {
        let name = it.next().unwrap();
        let delta: i128 = it.next().unwrap().parse().unwrap();
        *balances.entry(name).or_insert(0) += delta;
    }
    let output = balances
        .iter()
        .map(|(name, balance)| format!("{name}:{balance}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{output}");
}

