import sys


def main():
    lines = sys.stdin.buffer
    n = int(lines.readline())
    main_sum = 0
    opposite_sum = 0
    for row in range(n):
        for column in range(n):
            value = int(lines.readline())
            if row == column:
                main_sum += value
            if row + column == n - 1:
                opposite_sum += value
    print(abs(main_sum - opposite_sum))


if __name__ == "__main__":
    main()

