use std::collections::BTreeSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut values = BTreeSet::new();
    for _ in 0..n {
        values.insert(tokens.next().unwrap().parse::<i128>().unwrap());
    }
    println!("{}", values.iter().map(ToString::to_string).collect::<Vec<_>>().join(","));
}

source_texts.polynomial_value:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let degree: usize = tokens.next().unwrap().parse().unwrap();
    let coefficients: Vec<i128> = (0..=degree)
        .map(|_| tokens.next().unwrap().parse().unwrap())
        .collect();
    let x: i128 = tokens.next().unwrap().parse().unwrap();
    let value = coefficients.into_iter().fold(0_i128, |acc, coefficient| {
        acc * x + coefficient
    });
    println!("{value}");
}

