matrix_diagonal_difference.source_text:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let (mut main_sum, mut opposite_sum) = (0_i128, 0_i128);
    for row in 0..n {
        for column in 0..n {
            let value: i128 = tokens.next().unwrap().parse().unwrap();
            if row == column {
                main_sum += value;
            }
            if row + column + 1 == n {
                opposite_sum += value;
            }
        }
    }
    println!("{}", (main_sum - opposite_sum).abs());
}

