source_texts.nearest_pair_gap:
to main:
    let count be value of (ask for a number "")
    let values be an empty list of number
    repeat count times:
        add (value of (ask for a number "")) to values
    let best be (item 1 of values) - (item 2 of values)
    if best is less than 0:
        set best to 0 - best
    for each left from 1 to count - 1:
        for each right from left + 1 to count:
            let gap be (item left of values) - (item right of values)
            if gap is less than 0:
                set gap to 0 - gap
            if gap is less than best:
                set best to gap
    say best

