source_texts.postfix_evaluation:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    token_count = int(lines[0])
    stack = []
    for token in lines[1:token_count + 1]:
        if token in {"+", "-", "*"}:
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            else:
                stack.append(left * right)
        else:
            stack.append(int(token))
    print(stack[-1])


if __name__ == "__main__":
    main()

source_texts.balanced_brackets:
import sys


def main():
    text = sys.stdin.readline().rstrip("\n\r")
    stack = []
    matching = {")": "(", "]": "[", "}": "{"}
    for character in text:
        if character in "([{":
            stack.append(character)
        elif not stack or stack.pop() != matching[character]:
            print("no")
            return
    print("yes" if not stack else "no")


if __name__ == "__main__":
    main()

