use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut main_diagonal: i128 = 0;
    let mut opposite_diagonal: i128 = 0;
    for row in 0..n {
        for column in 0..n {
            let value: i128 = tokens.next().unwrap().parse().unwrap();
            if row == column {
                main_diagonal += value;
            }
            if row + column + 1 == n {
                opposite_diagonal += value;
            }
        }
    }
    println!("{}", (main_diagonal - opposite_diagonal).abs());
}

