use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut balances: BTreeMap<&str, i128> = BTreeMap::new();
    for _ in 0..n {
        let name = tokens.next().unwrap();
        let delta: i128 = tokens.next().unwrap().parse().unwrap();
        *balances.entry(name).or_insert(0) += delta;
    }
    let output = balances
        .iter()
        .map(|(name, balance)| format!("{name}:{balance}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{output}");
}

source_texts.sparse_dot_product:
use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut first: HashMap<u128, i128> = HashMap::with_capacity(n);
    for _ in 0..n {
        let index = tokens.next().unwrap().parse().unwrap();
        let value = tokens.next().unwrap().parse().unwrap();
        first.insert(index, value);
    }
    let m: usize = tokens.next().unwrap().parse().unwrap();
    let mut product: i128 = 0;
    for _ in 0..m {
        let index: u128 = tokens.next().unwrap().parse().unwrap();
        let value: i128 = tokens.next().unwrap().parse().unwrap();
        if let Some(first_value) = first.get(&index) {
            product += first_value * value;
        }
    }
    println!("{product}");
}

