use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let degree: usize = tokens.next().unwrap().parse().unwrap();
    let mut result: i128 = 0;
    let mut coefficients = Vec::with_capacity(degree + 1);
    for _ in 0..=degree {
        coefficients.push(tokens.next().unwrap().parse::<i128>().unwrap());
    }
    let x: i128 = tokens.next().unwrap().parse().unwrap();
    for coefficient in coefficients {
        result = result * x + coefficient;
    }
    println!("{result}");
}

sources.postfix_evaluation:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut stack: Vec<i128> = Vec::new();
    for _ in 0..n {
        let token = tokens.next().unwrap();
        match token {
            "+" | "-" | "*" => {
                let right = stack.pop().unwrap();
                let left = stack.pop().unwrap();
                stack.push(match token {
                    "+" => left + right,
                    "-" => left - right,
                    "*" => left * right,
                    _ => unreachable!(),
                });
            }
            number => stack.push(number.parse().unwrap()),
        }
    }
    println!("{}", stack.pop().unwrap());
}

